scan_table_check.script:
(function(engine, current) {
    var context = new global.EcsContext(current);
    var apiName = context.value('api_name');
    if (!apiName) {
        return;
    }
    var others = [];
    var other = new GlideRecord('sys_script_include');
    other.addQuery('api_name', apiName);
    other.addQuery('active', true);
    other.addQuery('sys_id', '!=', current.getUniqueValue());
    other.query();
    while (other.next()) {
        others.push('"' + other.getValue('name') + '" (' + other.getUniqueValue() + ')');
    }
    if (!others.length) {
        return;
    }
    var report = new global.EcsReport(engine, {
        ruleId: 'SN-SI-002',
        title: 'Duplicate Script Include API name',
        recommendation: 'Give each Script Include a unique name. With two active definitions of the same API name, ' +
            'which one callers get is undefined; rename or deactivate one of them.',
        current: current
    });
    report.addRecord('Script Include "' + context.value('name') + '" has the same API name (' + apiName + ') as active ' +
        'Script Include' + (others.length > 1 ? 's ' : ' ') + others.join(', ') + '.');
    engine.finding.setCurrentSource(current);
    report.flush();
})(engine, current);
